import {FaceDetector,FilesetResolver} from 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs';
const button=document.getElementById('camera'),status=document.getElementById('camera-status'),video=document.getElementById('video');let detector,stream,timer,lastSeen=0,lastFrame=-1;
function stop(){clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;window.room.face=false;button.innerHTML='Enable camera <span>↗</span>';status.textContent='Camera off. Your video was not recorded.'}
button.onclick=async()=>{if(stream){stop();return}button.disabled=true;status.textContent='Starting camera and loading local face detection…';try{stream=await navigator.mediaDevices.getUserMedia({video:{width:320,height:240,facingMode:'user'},audio:false});video.srcObject=stream;await video.play();if(!detector){const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');detector=await FaceDetector.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite'},runningMode:'VIDEO',minDetectionConfidence:.6})}button.innerHTML='Stop camera <span>×</span>';lastSeen=0;lastFrame=-1;timer=setInterval(()=>{if(video.readyState<2||lastFrame===video.currentTime)return;lastFrame=video.currentTime;try{const now=performance.now(),result=detector.detectForVideo(video,now);if(result.detections.length)lastSeen=now;window.room.face=lastSeen>0&&now-lastSeen<1500;if(!window.room.demo)status.textContent=window.room.face?'Face present. Confirm a woman is present to let time resume.':'No face in view. Move into the frame to become visible.'}catch{stop();status.textContent='Face tracking stopped. Retry the camera or use the camera-free demo.'}},180)}catch(e){stop();status.textContent=e.name==='NotAllowedError'?'Camera access was declined. You can allow it in browser settings or try the demo.':'Camera or face detection could not start. Check your connection, or try the demo.'}finally{button.disabled=false}};
window.addEventListener('pagehide',stop);

